-- $ cqlsh 127.0.0.1 9042
CREATE KEYSPACE IF NOT EXISTS shop
  WITH replication = {'class': 'NetworkTopologyStrategy', 'datacenter1': 3}
  AND durable_writes = true;

USE shop;
DESCRIBE KEYSPACES;     -- shop  system  system_auth  system_schema ...

-- dev-only single node
CREATE KEYSPACE IF NOT EXISTS sandbox
  WITH replication = {'class': 'SimpleStrategy', 'replication_factor': 1};

-- later: add a second data center, then run nodetool rebuild on its nodes
ALTER KEYSPACE shop
  WITH replication = {'class': 'NetworkTopologyStrategy', 'datacenter1': 3, 'dc2': 3};

CREATE TYPE IF NOT EXISTS shop.address (street text, city text, zip text);

CREATE TABLE shop.users (
  user_id    uuid PRIMARY KEY,
  email      text,
  tags       set<text>,
  prefs      map<text, text>,
  home       frozen<address>,
  balance    decimal,
  created_at timestamp
);

INSERT INTO shop.users (user_id, email, tags, prefs, home, balance, created_at)
VALUES (uuid(), 'ana@example.com', {'beta'}, {'lang': 'hy'},
        {street: 'Abovyan 1', city: 'Yerevan', zip: '0001'}, 12.50, toTimestamp(now()));

UPDATE shop.users SET tags = tags + {'vip'}, prefs['theme'] = 'dark'
WHERE user_id = 5b6962dd-3f90-4c93-8f61-eabfa4a803e2;

-- Q1: find a user by email (login)
CREATE TABLE shop.users_by_email (
  email text PRIMARY KEY, user_id uuid, name text, password_hash text);

-- Q2: list a user's orders, newest first
CREATE TABLE shop.orders_by_user (
  user_id uuid, placed_at timestamp, order_id uuid, total decimal, status text,
  PRIMARY KEY ((user_id), placed_at, order_id)
) WITH CLUSTERING ORDER BY (placed_at DESC, order_id ASC);

-- Q3: show one order with its items
CREATE TABLE shop.order_items (
  order_id uuid, sku text, name text, qty int, price decimal,
  PRIMARY KEY ((order_id), sku));

-- placing an order writes to orders_by_user AND order_items

CREATE TABLE shop.sessions (
  token text PRIMARY KEY, user_id uuid, data text
) WITH default_time_to_live = 86400;          -- 1 day unless overridden

INSERT INTO shop.sessions (token, user_id, data)
VALUES ('t-abc', 5b6962dd-3f90-4c93-8f61-eabfa4a803e2, '{}') USING TTL 3600;

SELECT TTL(data), WRITETIME(data) FROM shop.sessions WHERE token = 't-abc';
--  ttl(data) | writetime(data)
--       3598 | 1760691600123456

-- sliding expiry: rewrite with a fresh TTL on each request
UPDATE shop.sessions USING TTL 3600 SET data = '{"cart": 2}' WHERE token = 't-abc';

-- cqlsh: the session consistency level applies to following statements
CONSISTENCY LOCAL_QUORUM;
INSERT INTO shop.users_by_email (email, user_id, name)
VALUES ('ana@example.com', 5b6962dd-3f90-4c93-8f61-eabfa4a803e2, 'Ana');

CONSISTENCY ONE;      -- fast, possibly stale read
SELECT name FROM shop.users_by_email WHERE email = 'ana@example.com';

-- With RF = 3:
--   W=QUORUM(2) + R=QUORUM(2) = 4 > 3 -> reads see the latest acknowledged write
--   W=ONE(1)    + R=ONE(1)    = 2     -> may read stale data
--   W=ALL(3)    + R=ONE(1)    = 4     -> consistent, but any down node fails writes

-- keep two denormalized tables in sync: all-or-nothing (eventually)
BEGIN BATCH
  INSERT INTO shop.users_by_email (email, user_id, name)
  VALUES ('ana@example.com', 5b6962dd-3f90-4c93-8f61-eabfa4a803e2, 'Ana');
  INSERT INTO shop.users (user_id, email)
  VALUES (5b6962dd-3f90-4c93-8f61-eabfa4a803e2, 'ana@example.com');
APPLY BATCH;

-- single-partition batch: atomic and isolated, no batchlog needed
BEGIN UNLOGGED BATCH
  INSERT INTO shop.order_items (order_id, sku, qty) VALUES (9a3e3b6e-0e4d-4c39-9a52-6a8f1f5c2b11, 'PEN', 3);
  INSERT INTO shop.order_items (order_id, sku, qty) VALUES (9a3e3b6e-0e4d-4c39-9a52-6a8f1f5c2b11, 'PAD', 1);
APPLY BATCH;

CREATE INDEX IF NOT EXISTS orders_status ON shop.orders_by_user (status) USING 'sai';
CREATE INDEX IF NOT EXISTS orders_total  ON shop.orders_by_user (total)  USING 'sai';

-- cheap: partition key + index
SELECT order_id, total FROM shop.orders_by_user
WHERE user_id = 5b6962dd-3f90-4c93-8f61-eabfa4a803e2 AND status = 'open';

-- cluster-wide: fine for selective, occasional queries with a LIMIT
SELECT user_id, order_id FROM shop.orders_by_user
WHERE status = 'open' AND total > 500 LIMIT 50;

-- vector similarity search (5.0)
CREATE TABLE shop.docs (id int PRIMARY KEY, body text, embedding vector<float, 3>);
CREATE INDEX ON shop.docs (embedding) USING 'sai';
SELECT id, body FROM shop.docs ORDER BY embedding ANN OF [0.1, 0.8, 0.3] LIMIT 3;
